```csharp[]
public class Solution
{
    public IList<IList<string>> SolveNQueens(int n)
    {
        // Raj Thomas 2nd July 2026 10:30PM IST

        // create board
        char[][] board = new char[n][];
        for(int i = 0; i < n; i++) {
            board[i] = new char[n];
            for(int j = 0; j < n; j++) {
                board[i][j] = '.';
            }
        }

        IList<IList<string>> result = new List<IList<string>>();
        int startRowId = 0;
        BackTrack(board, startRowId, n, result);

        return result;
    }

    private void BackTrack(char[][] board, int rowIdx, int n, IList<IList<string>> result) {

        // base condition
        if(rowIdx == n) {
            IList<string> solvedBoard = new List<string>();
            for(int i = 0; i < n; i++) {
                solvedBoard.Add(new string(board[i]));
            }

            result.Add(solvedBoard);
            return;
        }

        // iterative BackTrack
        for(int colIdx = 0; colIdx < n; colIdx++) {

            if(IsPossibleToPlaceQueen(board, rowIdx, colIdx, n)) {
                board[rowIdx][colIdx] = 'Q';
                BackTrack(board, rowIdx + 1, n, result);
            }

            board[rowIdx][colIdx] = '.';
        }

    }

    private bool IsPossibleToPlaceQueen(char[][] board, int rowIdx, int colIdx, int n) {

        // check top
        int r = rowIdx, c = colIdx; 
        while(r >= 0) {
            if(board[r][c] == 'Q') return false;
            r--;
        }

        // check top right diagonal
        r = rowIdx;
        c = colIdx; 
        while(r >= 0 && c < n) {
            if(board[r][c] == 'Q') return false;
            r--;
            c++;
        }

        // check top left diagonal
        r = rowIdx;
        c = colIdx; 
        while(r >= 0 && c >= 0) {
            if(board[r][c] == 'Q') return false;
            r--;
            c--;
        }

        return true;

    }
}
